package app.metrolife;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Path;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

/** Durable shared departures with traveller-only schedule time and real hub authority. No wall-clock sleeps. */
class TransitTests {
 @TempDir Path dir;ObjectMapper mapper=new ObjectMapper();GameService g;long now=1000000000;String token;
 @BeforeEach void setup()throws Exception{g=new GameService(new JsonStore(mapper,dir.resolve("save.json").toString()),new Content(mapper),mapper);g.time=()->now;token=create("atl");}
 String create(String city){String t=g.guest(null,g.object()).token();ActivityFixture.setup(g,t,g.object().put("city",city).put("neighborhood",g.content.city(city).path("neighborhoods").get(0).path("id").asText()).put("aspiration","founder"));online(t);return t;}
 ObjectNode sim(String t){return g.sim(g.session(t,true));}ObjectNode world(){return g.world(g.session(token,true));}
 void online(String t){g.community.online.put("public:"+sim(t).path("userId").asText(),now);}
 void hub(String t,String mode){ObjectNode s=sim(t);s.put("loc",g.transit.hub(s.path("city").asText(),mode));s.remove("position");g.navigation.position(s);}
 ObjectNode book(String t,String to,String mode){return g.bookTransit(t,g.object().put("to",to).put("mode",mode).put("confirmTimeAdvance",true).put("confirm",true));}
 
 
 @Test void sameDepartureSharesSeatsPassengerListPrivateChatAndIsolatedPersonalTime(){String other=create("atl"),outsider=create("atl");hub(token,"bus");hub(other,"bus");JsonNode home=sim(token).path("home").deepCopy();JsonNode a=book(token,"nyc","bus").path("sim").path("trip");now+=1000;JsonNode b=book(other,"nyc","bus").path("sim").path("trip");assertEquals(a.path("id"),b.path("id"));assertNotEquals(a.path("seat"),b.path("seat"));assertEquals(2,b.path("passengers").size());assertEquals(2455,sim(token).path("cash").asInt());assertEquals("On the bus to New York",g.community.player(sim(token),"public").path("travelStatus").asText());assertEquals(a.path("id"),g.community.player(sim(token),"public").path("tripId"));assertFalse(g.community.near(sim(token),sim(outsider)));g.chatTransit(token,g.object().put("text","See you at the station"));assertEquals(1,g.chat(other,"atl").path("messages").size());assertTrue(g.chat(outsider,"atl").path("messages").isEmpty());long target=world().path("startedAt").asLong();now=a.path("arriveAt").asLong();long naturalMinutes=g.absoluteMinutes(world()),worldOffset=world().path("transitMinutes").asLong();double neighbourCash=sim(outsider).path("cash").asDouble();g.getSim(other);assertEquals(naturalMinutes,g.absoluteMinutes(world()));assertEquals(480,g.absoluteMinutes(world())+sim(other).path("scheduleMinutes").asLong()-540);long offset=sim(other).path("scheduleMinutes").asLong();for(String t:List.of(token,other)){JsonNode arrived=g.getSim(t).path("sim");assertEquals("nyc",arrived.path("city").asText());assertEquals("nycBus",arrived.path("loc").asText());assertTrue(arrived.path("trip").isNull());assertTrue(arrived.path("position").path("room").isNull());assertEquals(offset,arrived.path("scheduleMinutes").asLong());assertEquals(17,arrived.path("personalSchedule").path("hour").asInt());}JsonNode neighbour=g.getSim(outsider).path("sim");assertEquals(0,neighbour.path("scheduleMinutes").asLong());assertEquals(neighbourCash,neighbour.path("cash").asDouble());assertTrue(neighbour.path("needs").path("energy").asDouble()>sim(token).path("needs").path("energy").asDouble());assertEquals(home,sim(token).path("home"));assertEquals(worldOffset,world().path("transitMinutes").asLong());assertEquals(target,world().path("startedAt").asLong());assertTrue(Math.hypot(sim(token).path("position").path("x").asDouble()-sim(other).path("position").path("x").asDouble(),sim(token).path("position").path("z").asDouble()-sim(other).path("position").path("z").asDouble())>=.85);}
 @Test void napEventsAndCommittedFareSurviveRestartAndSettleExactlyOnce()throws Exception{hub(token,"bus");sim(token).withObject("needs").put("energy",50);JsonNode trip=book(token,"nyc","bus").path("sim").path("trip");g.napTransit(token);assertEquals(409,assertThrows(ApiException.class,()->g.napTransit(token)).status);assertEquals(409,assertThrows(ApiException.class,()->g.cancelAction(token)).status);now=trip.path("departAt").asLong()+30000;g.getSim(token);int events=g.transit.trip(sim(token)).path("events").size();assertTrue(events>=1&&events<=2);double social=sim(token).path("needs").path("social").asDouble();g.getSim(token);assertEquals(social,sim(token).path("needs").path("social").asDouble());g.store.save();GameService restored=new GameService(new JsonStore(mapper,dir.resolve("save.json").toString()),new Content(mapper),mapper);restored.time=()->now;assertEquals(trip.path("id"),restored.getSim(token).path("sim").path("trip").path("id"));assertEquals("transit:"+trip.path("id").asText(),restored.sim(restored.session(token,true)).path("position").path("room").asText());now=trip.path("arriveAt").asLong();JsonNode arrived=restored.getSim(token).path("sim");assertTrue(arrived.path("needs").path("energy").asDouble()>50);assertEquals(2455,arrived.path("cash").asInt());assertEquals(arrived,restored.getSim(token).path("sim"));}
 @Test void simultaneousDifferentRoutesKeepIndependentSchedulesAndLeaveWorldTimeNatural(){String other=create("atl");hub(token,"bus");hub(other,"plane");JsonNode bus=book(token,"nyc","bus").path("sim").path("trip"),plane=book(other,"bay","plane").path("sim").path("trip");now=plane.path("arriveAt").asLong();long natural=g.absoluteMinutes(world());g.getSim(other);assertEquals(natural,g.absoluteMinutes(world()));assertEquals(120,natural+sim(other).path("scheduleMinutes").asLong()-540);long planeOffset=sim(other).path("scheduleMinutes").asLong();now=bus.path("arriveAt").asLong();natural=g.absoluteMinutes(world());g.getSim(token);assertEquals(natural,g.absoluteMinutes(world()));assertEquals(480,natural+sim(token).path("scheduleMinutes").asLong()-540);assertEquals(planeOffset,sim(other).path("scheduleMinutes").asLong());assertEquals("bayAirport",sim(other).path("loc").asText());}
 @Test void busCrossingPersonalMidnightLeavesSharedRentDayUnchangedAndMoveIsSeparate(){world().put("startedAt",now-8*60000);g.getSim(token);hub(token,"bus");JsonNode oldHome=sim(token).path("home").deepCopy(),trip=book(token,"nyc","bus").path("sim").path("trip");now=trip.path("arriveAt").asLong();g.getSim(token);assertEquals(2455,sim(token).path("cash").asInt());assertEquals(1,g.clock(world()).path("day").asInt());assertEquals(2,g.scheduleClock(sim(token),world()).path("day").asInt());assertEquals(oldHome,sim(token).path("home"));String nh=g.content.city("nyc").path("startingLife").path("neighborhood").asText();JsonNode moved=g.moveHome(token,g.object().put("city","nyc").put("neighborhood",nh).put("confirm",true)).path("sim");assertEquals(2400,moved.path("cash").asInt());assertEquals("nyc",moved.path("home").path("city").asText());assertEquals("home",moved.path("position").path("place").asText());assertTrue(moved.path("position").path("room").isNull());}
 @Test void schedulerSettlesOfflinePassengersWithoutConnectedClients(){hub(token,"plane");JsonNode trip=book(token,"nyc","plane").path("sim").path("trip");now=trip.path("arriveAt").asLong();long natural=g.absoluteMinutes(world());LiveWire wire=new LiveWire(g);try{wire.tick();assertFalse(g.transit.active(sim(token)));assertEquals("nyc",sim(token).path("city").asText());assertEquals(natural,g.absoluteMinutes(world()));assertEquals(120,natural+sim(token).path("scheduleMinutes").asLong()-540);}finally{wire.close();}}
}
